// Get flashcard data
const data = $input.first().json;

// Determine embed color based on difficulty
const difficultyColors = {
  'easy': 5763719,    // Green
  'medium': 16776960, // Yellow
  'hard': 15548997    // Red
};

const color = difficultyColors[data.difficulty.toLowerCase()] || 3447003; // Default blue

// Format the Discord embed
const embed = {
  "embeds": [{
    "title": `📚 Daily Flashcard - ${data.topic_name}`,
    "description": `**Difficulty:** ${data.difficulty.charAt(0).toUpperCase() + data.difficulty.slice(1)}\n\nTime to keep your study streak going! 🔥`,
    "color": color,
    "fields": [
      {
        "name": "❓ Question",
        "value": data.question,
        "inline": false
      },
      {
        "name": "💡 Answer",
        "value": `||${data.answer}||`,
        "inline": false
      },
      {
        "name": "📊 Your Progress",
        "value": `**Accuracy:** ${data.user_progress.accuracy}%\n**Streak:** ${data.user_progress.streak_days} days\n**Cards Reviewed:** ${data.user_progress.flashcards_reviewed}`,
        "inline": false
      }
    ],
    "footer": {
      "text": "💡 Open the app to study and improve your progress!"
    },
    "timestamp": new Date().toISOString()
  }]
};

return { json: embed };
